-- 2. Ajustar posiciones de preguntas existentes para hacer espacio
update public.questions
set position = position + 1
where survey_version_id = 'b1000000-0000-4000-8000-000000000004'
  and position >= 4;

-- 3. Insertar la pregunta demo_province después de demo_ccaa
